      "description": "Player must navigate to and visually locate the magenta concrete powder pillar landmark",
      "rules": [
        {
          "type": "position_inside_box",
          "description": "Player is within 4 blocks of the magenta concrete powder pillar (centered at ~7, ~2, ~6)",
          "params": {
            "x_min": 4,
            "x_max": 10,
            "y_min": -1,
            "y_max": 6,
            "z_min": 3,
